	// A: i x j (i = 0..n-1, j = 0..m-1)
	// r: i
	// p: j
	using namespace noarr;

	auto n_len = A | get_length<'i'>();
	auto m_len = A | get_length<'j'>();

	// p[j] = (j % m) / m
	traverser(p).for_each([=](auto state) {
		auto j = get_index<'j'>(state);
		p[state] = (num_t)(j % m_len) / (num_t)m_len;
	});

	// r[i] = (i % n) / n
	// A[i][j] = (i * (j + 1) % n) / n
	traverser(A, r).template for_dims<'i'>([=](auto trav_i) {
		auto state_i = trav_i.state();
		auto i = get_index<'i'>(state_i);

		r[state_i] = (num_t)(i % n_len) / (num_t)n_len;

		trav_i.for_each([=](auto state_ij) {
			auto j = get_index<'j'>(state_ij);
			A[state_ij] = (num_t)(i * (j + 1) % n_len) / (num_t)n_len;
		});
	});
