// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "bicg.hpp"

using num_t = DATA_TYPE;

namespace {

// convenient aliases for dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>(); // dimension over N (size n)
constexpr auto j_vec = noarr::vector<'j'>(); // dimension over M (size m)

// layout tuning (separated so data layout can be changed without touching the kernel)
struct tuning {
	// A: i x j (N x M)
	DEFINE_PROTO_STRUCT(A_layout, j_vec ^ i_vec); // 'j' outer, 'i' inner

	// s, p: length M, dimension 'j'
	DEFINE_PROTO_STRUCT(s_layout, j_vec);
	DEFINE_PROTO_STRUCT(p_layout, j_vec);

	// q, r: length N, dimension 'i'
	DEFINE_PROTO_STRUCT(q_layout, i_vec);
	DEFINE_PROTO_STRUCT(r_layout, i_vec);
} tuning;

// Array initialization.
// A: i x j (N x M)
// r: length N, indexed by 'i'
// p: length M, indexed by 'j'
void init_array(auto A, auto r, auto p) {
	using namespace noarr;

	// lengths in each dimension
	auto n_len = A | get_length<'i'>(); // corresponds to n (N)
	auto m_len = A | get_length<'j'>(); // corresponds to m (M)

	// Initialize p[j] = (j % m) / m
	traverser(p).for_each([=](auto state) {
		auto j = get_index<'j'>(state);
		p[state] = (num_t)(j % m_len) / m_len;
	});

	// Initialize r[i] and A[i][j]
	traverser(A).template for_dims<'i'>([=](auto trav_i) {
		// trav_i has 'i' fixed, 'j' free
		auto state_i = trav_i.state();
		auto i = get_index<'i'>(state_i);

		// r[i] = (i % n) / n
		r[state_i] = (num_t)(i % n_len) / n_len;

		// A[i][j] = (i * (j + 1) % n) / n
		trav_i.for_each([=](auto state) {
			auto j = get_index<'j'>(state);
			A[state] = (num_t)((i * (j + 1)) % n_len) / n_len;
		});
	});
}

// Main computational kernel.
// A: i x j (N x M)
// s, p: length M, dimension 'j'
// q, r: length N, dimension 'i'
[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	#pragma scop
	// First loop: for (i = 0; i < M; i++) s[i] = 0;
	traverser(s).for_each([=](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// Second loop:
	// for (i = 0; i < N; i++) {
	//   q[i] = 0;
	//   for (j = 0; j < M; j++) {
	//     s[j] = s[j] + r[i] * A[i][j];
	//     q[i] = q[i] + A[i][j] * p[j];
	//   }
	// }
	traverser(q, r, A, p, s).template for_dims<'i'>([=](auto trav_i) {
		// Outer loop over i: initialize q[i] = 0
		q[trav_i] = SCALAR_VAL(0.0);

		// Inner loop over j
		trav_i.for_each([=](auto state) {
			// state carries both 'i' and 'j'
			// s uses 'j', r uses 'i', A uses 'i','j', q uses 'i', p uses 'j'
			s[state] += r[state] * A[state];
			q[state] += A[state] * p[state];
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Retrieve problem size
	std::size_t n = N;
	std::size_t m = M;

	// Set lengths for all relevant dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(m);

